//! Workload strings, generated by the pure functions in zgx's `comparisons/workload`.
#![allow(dead_code)]
use zgx_workload::{heavy, vlist, Workload};

pub fn font_bytes() -> &'static [u8] {
    zgx_workload::FONT_BYTES
}

/// The ~80 numeric value labels that change every tick of heavy/stream, with the font size
/// zgx's heavy view draws them at (tile 20, card 16, table cell 12).
pub fn heavy_numeric(live: u64) -> Vec<(String, f32)> {
    let mut v = vec![];
    for t in 0..heavy::TILES {
        v.push((heavy::tile_value(t, live), 20.));
    }
    for c in 0..heavy::CARDS {
        v.push((heavy::card_value(c, live), 16.));
    }
    for r in heavy::row_range(0.) {
        v.push((heavy::row_latency(r, live), 12.));
        v.push((heavy::row_throughput(r, live), 12.));
    }
    v
}

/// Labels that do not change tick to tick (shaped on mount/scroll): short UI labels.
pub fn heavy_static(live: u64) -> Vec<(String, f32)> {
    let mut v = vec![(heavy::TITLE.to_string(), 18.)];
    for t in 0..heavy::TILES {
        v.push((heavy::tile_label(t).to_string(), 11.));
    }
    for c in 0..heavy::CARDS {
        v.push((heavy::card_title(c), 11.));
    }
    for (_, title) in heavy::COLUMNS {
        v.push((title.to_string(), 11.));
    }
    for r in heavy::row_range(0.) {
        v.push((heavy::row_id(r), 12.));
        v.push((heavy::row_worker(r), 12.));
        v.push((heavy::status(r, live).0.to_string(), 10.));
    }
    v
}

/// The heavy log lines (one is pushed per tick; five are visible).
pub fn heavy_log_lines(n: usize) -> Vec<String> {
    let mut h = heavy::Heavy::from_env();
    h.mode = zgx_workload::Mode::Stream;
    let mut out = vec![];
    for _ in 0..n {
        h.tick();
        out.push(h.log.back().unwrap().clone());
    }
    out
}

/// Lab streaming text: 105-character lines of "NNNNNN The quick brown fox streams a token. ".
pub fn lab_stream_lines(ticks: usize) -> Vec<String> {
    let mut w = Workload::from_env();
    w.mode = zgx_workload::Mode::Stream;
    for _ in 0..ticks {
        w.tick();
    }
    w.visible_text().split('\n').map(|s| s.to_string()).collect()
}

pub fn vlist_paragraphs(rows: std::ops::Range<usize>) -> Vec<String> {
    rows.map(vlist::text).collect()
}

pub fn vlist_meta(rows: std::ops::Range<usize>) -> Vec<String> {
    let mut v = vec![];
    for r in rows {
        v.push(vlist::author(r));
        v.push(vlist::time(r));
    }
    v
}

/// Everything, for the exactness tests.
pub fn all_workload_strings() -> Vec<String> {
    let mut v = vec![];
    for live in 0..1500u64 {
        v.extend(heavy_numeric(live).into_iter().map(|x| x.0));
    }
    for live in [0, 7, 100, 20_000] {
        v.extend(heavy_static(live).into_iter().map(|x| x.0));
    }
    // Rows beyond the first screen.
    for r in (0..100_000).step_by(37) {
        v.push(heavy::row_id(r));
        v.push(heavy::row_worker(r));
        v.push(heavy::row_latency(r, r as u64));
        v.push(heavy::row_throughput(r, r as u64));
    }
    v.extend(heavy_log_lines(2000));
    for t in [1usize, 50, 400, 2000] {
        v.extend(lab_stream_lines(t));
    }
    v.push(zgx_workload::TOKEN.to_string());
    v.push(zgx_workload::busy::paragraph_line(3));
    v.push(zgx_workload::animation::SHIMMER.to_string());
    v.push(zgx_workload::row_label(12));
    v.extend(vlist_paragraphs(0..400));
    v.extend(vlist_meta(0..2000));
    for i in 0..1000 {
        v.push(zgx_workload::micro::static_label(i));
        v.push(zgx_workload::micro::counter_label(i as u64 * 7919));
        v.push(zgx_workload::micro::fixed_label(i));
    }
    v
}
